# Analyze f(n) = n^2 + 2n + 2 for small n
# We check if f(n) only has prime factors 2 and 5.
# We check up to n=10.
def is_valid(n):
    val = n**2 + 2*n + 2
    if val <= 0:
        return False
    d = 2
    temp = val
    while d * d <= temp:
        if temp % d == 0:
            if d > 5 and d != 2 and d != 5: # Check if any other prime factor exists
                return False
            while temp % d == 0:
                temp //= d
        d += 1
    if temp > 1 and temp != 2 and temp != 5:
        return False
    return True

print("n | n^2 + 2n + 2 | Valid (2/5 factors only)")
for n in range(11):
    valid = is_valid(n)
    print(f"{n} | {n**2 + 2*n + 2} | {valid}")

def D(n):
    return n**3 + 4*n**2 + 6*n + 4

def is_2_5_power(number):
    if number <= 0:
        return False

    # Divide out factors of 2 and 5
    while number % 2 == 0:
        number //= 2
    while number % 5 == 0:
        number //= 5

    # If the remainder is 1, it is of the form 2^c * 5^d
    return number == 1

candidates = [
    0, 2, 3, 6, 8, 14, 18, 23, 30, 38, 48, 62, 78, 98
]

results = {}
print("--- Checking Candidates ---")
for n in candidates:
    d_n = D(n)
    is_power = is_2_5_power(d_n)

    if is_power:
        # For solutions, we should also verify the divisibility condition, 
        # but the task only asks to check if D(n) is of the form 2^c 5^d.
        pass 

    results[n] = (d_n, is_power)

print("\nResults (n, D(n), is_2_5_power):")
for n, (d_n, is_power) in sorted(results.items()):
    print(f"n={n}: D(n)={d_n}, is_2_5_power={is_power}")

print("\nList of candidates where D(n) is of the form 2^c 5^d:")
power_candidates = [n for n, (d_n, is_power) in results.items() if is_power]
